<?php
declare(strict_types=1);
defined('VV_ROOT') || exit;
$query=\VV\Content::text(val($_GET,'q'),120);$kind=val($_GET,'kind');$access=val($_GET,'access');
$items=array_filter($vv->state['media'],static function($m)use($query,$kind,$access):bool {
    if($query!==''&&mb_stripos($m['name'].' '.$m['alt'].' '.($m['alt_en']??''),$query)===false)return false;
    if($kind==='image'&&\VV\Media::document($m))return false;
    if($kind==='document'&&!\VV\Media::document($m))return false;
    return !($access==='public'&&!$m['public'])&&!($access==='private'&&$m['public']);
});uasort($items,fn($a,$b)=>strcmp($b['created_at'],$a['created_at']));
?>
<section class="panel"><div class="panel-title"><h2><?=e(t('Ajouter un fichier','Add a file'))?></h2><a class="button secondary small" href="<?=e(admin_url('quarantine'))?>"><?=e(t('Examiner la quarantaine','Review quarantine'))?></a></div>
<form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="media.upload"><div class="two"><label><?=e(t('Image ou document, 8 Mo maximum','Image or document, 8 MB maximum'))?><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp,.pdf,.docx,.zip,.csv" required></label><label><?=e(t('Texte alternatif FR','French alt text'))?><input name="alt" maxlength="250"></label></div><label class="checkbox"><input type="checkbox" name="public"><?=e(t('Rendre public après validation et libération','Make public after validation and release'))?></label><button class="button primary"><?=e(t('Déposer en quarantaine','Deposit in quarantine'))?></button></form><p class="hint"><?=e(t('Les octets et le format d’origine sont conservés. Aucun fichier reçu n’est immédiatement publié.','Original bytes and format are preserved. No received file is published immediately.'))?></p></section>
<form class="panel media-filters" method="get"><input type="hidden" name="view" value="media"><input type="hidden" name="lang" value="<?=e(lang())?>"><label><?=e(t('Rechercher','Search'))?><input type="search" name="q" value="<?=e($query)?>"></label><label><?=e(t('Format','Format'))?><select name="kind"><option value=""><?=e(t('Tous','All'))?></option><option value="image" <?=$kind==='image'?'selected':''?>>Images</option><option value="document" <?=$kind==='document'?'selected':''?>>Documents</option></select></label><label><?=e(t('Accès','Access'))?><select name="access"><option value=""><?=e(t('Tous','All'))?></option><option value="public" <?=$access==='public'?'selected':''?>><?=e(t('Public','Public'))?></option><option value="private" <?=$access==='private'?'selected':''?>><?=e(t('Privé','Private'))?></option></select></label><button class="button secondary"><?=e(t('Filtrer','Filter'))?></button></form>
<p class="hint"><?=count($items)?> <?=e(t('fichiers libérés','released files'))?></p><div class="media-grid">
<?php foreach($items as$m):?><article class="media-card"><div class="media-visual"><?php if(!\VV\Media::document($m)):?><img src="<?=e(url('media.php',['id'=>$m['id']]))?>" alt="<?=e($m['alt'])?>" loading="lazy"><?php else:?><strong><?=e(strtoupper($m['extension']))?></strong><?php endif;?></div><div class="media-info"><h3><?=e($m['name'])?></h3><p class="hint"><?=e($m['mime'])?> · <?=e(number_format($m['size']/1024,1))?> Ko</p><span class="badge <?=$m['public']?'green':''?>"><?=e($m['public']?t('Public','Public'):t('Privé','Private'))?></span><div class="button-row"><a class="button secondary small" href="<?=e(url('media.php',['id'=>$m['id'],'download'=>'1']))?>"><?=e(t('Télécharger','Download'))?></a><button class="button secondary small" type="button" data-copy="<?=e(url('media.php',['id'=>$m['id']]))?>"><?=e(t('Copier le lien','Copy link'))?></button></div>
<details><summary><?=e(t('Métadonnées FR / EN et accès','FR / EN metadata and access'))?></summary><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="media.update"><input type="hidden" name="id" value="<?=e($m['id'])?>"><label><?=e(t('Nom du fichier, même extension','Filename, same extension'))?><input name="name" value="<?=e($m['name'])?>" required maxlength="160"></label><label><?=e(t('Texte alternatif FR','French alt text'))?><input name="alt" value="<?=e($m['alt'])?>" maxlength="250"></label><label><?=e(t('Texte alternatif EN','English alt text'))?><input name="alt_en" value="<?=e($m['alt_en']??'')?>" maxlength="250"></label><label class="checkbox"><input type="checkbox" name="public" <?=$m['public']?'checked':''?>><?=e(t('Public','Public'))?></label><label><?=e(t('Mot de passe actuel','Current password'))?><input type="password" name="current_password" autocomplete="current-password" required></label><button class="button secondary small"><?=e(t('Enregistrer','Save'))?></button></form><?=action_form('media.delete',t('Supprimer ce fichier','Delete file'),['id'=>$m['id']],'danger small',true)?></details></div></article><?php endforeach;?></div>
